TEXTS = {"en": EN, "ru": RU}


def tx(lang: str, key: str, **kw) -> str:
    s = TEXTS.get(lang, EN).get(key, EN[key])
    return s.format(**kw) if kw else s


def label(lang: str, group: str, key: str) -> str:
    return TEXTS.get(lang, EN)[group].get(key, EN[group].get(key, key))
